<?php

declare(strict_types=1);

/*
 * Regenerates resources/encodings/*.php: byte → UTF-8 tables for single-byte code pages
 * and the canonical composition pairs ANSEL decoding needs when ext-intl is missing.
 * Dev-only: needs ext-iconv and ext-intl. The library itself reads the generated files
 * and has no runtime dependency on either extension.
 */

use Korin\Gedcom\Io\Codec\AnselCodec;

require __DIR__ . '/../vendor/autoload.php';

const CODE_PAGES = [
    'cp1250' => 'CP1250',
    'cp1251' => 'CP1251',
    'cp1252' => 'CP1252',
    'cp437' => 'CP437',
    'cp850' => 'CP850',
    'macroman' => 'MACINTOSH',
];

$out = __DIR__ . '/../resources/encodings';

/**
 * @param array<int|string, string> $map
 */
function export(string $file, string $comment, array $map): void
{
    $lines = [];
    foreach ($map as $key => $value) {
        $lines[] = sprintf('    %s => %s,', is_int($key) ? sprintf('0x%02X', $key) : var_export($key, true), var_export($value, true));
    }
    file_put_contents($file, "<?php\n\ndeclare(strict_types=1);\n\n// {$comment}\n// Generated by bin/generate-encoding-tables.php; do not edit.\n\nreturn [\n" . implode("\n", $lines) . "\n];\n");
}

foreach (CODE_PAGES as $file => $iconvName) {
    $map = [];
    for ($byte = 0x80; $byte <= 0xFF; ++$byte) {
        $char = @iconv($iconvName, 'UTF-8', chr($byte));
        if ($char !== false && $char !== '') {
            $map[$byte] = $char;
        }
    }
    export("{$out}/{$file}.php", "{$iconvName}: bytes 0x80–0xFF → UTF-8. Missing bytes are undefined in the code page.", $map);
    printf("%-9s %3d bytes\n", $file, count($map));
}

// Pairs "base + combining mark" → precomposed character, limited to marks ANSEL can express.
$marks = array_flip(AnselCodec::COMBINING);
$pairs = [];
for ($cp = 0xC0; $cp <= 0x2FFFF; ++$cp) {
    $char = IntlChar::chr($cp);
    if (Normalizer::normalize($char, Normalizer::NFC) !== $char) {
        continue;
    }
    $raw = Normalizer::getRawDecomposition($char);
    if (!is_string($raw) || mb_strlen($raw) !== 2) {
        continue;
    }
    if (isset($marks[mb_substr($raw, 1)])) {
        $pairs[$raw] = $char;
    }
}
ksort($pairs, SORT_STRING);
export("{$out}/ansel-compose.php", 'Canonical composition pairs (base . mark => composed) for ANSEL combining marks.', $pairs);
printf("%-9s %3d pairs\n", 'compose', count($pairs));
